const fs = await import('node:fs');
const markdownPath = globalThis.input.markdown_path;
if (!fs.existsSync(markdownPath)) throw new Error('Markdown file not found');
globalThis.markdownPath = markdownPath;
globalThis.pdfPath = markdownPath.replace(/\\.md$/i, '.pdf');

const markdownpdf = (await import('markdown-pdf')).default;
await new Promise((resolve, reject) => {
  markdownpdf().from(globalThis.markdownPath).to(globalThis.pdfPath, function (err) {
    if (err) return reject(err);
    resolve();
  });
});
const { readFileSync } = await import('node:fs');
const pdfBuffer = readFileSync(globalThis.pdfPath);
globalThis.pdfBase64 = pdfBuffer.toString('base64');
